while (Get-Process -Id 36420 -ErrorAction SilentlyContinue) { Start-Sleep 60 }
"build_manifest exited $(Get-Date -Format t)"
$today = (Get-Date).Date
for ($i = 0; $i -lt 45; $i++) {
  $m = Get-Item "$d\manifest.csv"; $t = Get-Item "$d\triage.csv"
  $busy = Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'triage_rules' }
  if ($m.LastWriteTime.Date -eq $today -and $t.LastWriteTime -gt $m.LastWriteTime -and -not $busy) { "triage_rules done $(Get-Date -Format t)"; break }
  Start-Sleep 20
}
Get-ChildItem $d -File | Where-Object Name -in 'manifest.csv','triage.csv','unclassified.csv' | ForEach-Object { "$($_.Name) $($_.Length) $($_.LastWriteTime)" }
Get-Content "$d\run_wide.log" -Tail 3

