import csv, glob, re, json
labels = {}
for f in sorted(glob.glob("config/model_labels/*.csv")):
    for r in csv.DictReader(open(f, encoding="utf-8")):
        labels[r["key"]] = r
a_keys = {k for k, r in labels.items() if r["candidate"] == "yes" and r["route"] != "skip"}
mp = {r["key"]: r for r in csv.DictReader(open("data/triage_model_pass.csv", encoding="utf-8-sig"))}
print("label rows:", len(labels), "candidate keys:", len(a_keys), "sample key:", next(iter(a_keys)))
print("model-pass cols:", list(next(iter(mp.values())).keys())[:16])
tri = list(csv.DictReader(open("data/triage.csv", encoding="utf-8-sig")))
man = list(csv.DictReader(open("data/manifest.csv", encoding="utf-8-sig")))
cfg = json.load(open("config/roots.json", encoding="utf-8"))
ex = re.compile(cfg["exclude_path_regex"].replace("(?i)", ""), re.I)
lost = [k for k in a_keys if not (k in mp and mp[k].get("tier") == "A")]
print("candidate keys not tier A now:", len(lost))
def find(rows, k):
    return [r for r in rows if k in (r.get("md5"), r.get("dup_key"), r.get("id"), r.get("key"))]
for k in lost:
    t = find(tri, k)
    mm = find(man, k)
    canon = [r for r in mm if r["canonical"] == "True"]
    why = []
    if not mm: why.append("not in manifest")
    elif not canon: why.append("no canonical row")
    else:
        c = canon[0]
        if ex.search(f"{c['source']}/{c['path']}"): why.append("excluded")
        if t: why.append(f"rules-classified as {t[0].get('disciplines','')[:40]}")
        why.append(f"canonical {c['source']}/{c['path'][:70]}")
    print(" -", labels[k]["reason"][:60], "|", "; ".join(why))

