# Dedup: md5 when Drive has one (binary files), else name+size (Google-native files).
foreach ($g in ($rows | Group-Object { if ($_.md5) { "md5:$($_.md5)" } else { "ns:$($_.name.ToLower())|$($_.size)" } })) {
  # Reference-only roots (Zotero's attachment store) are never the canonical copy, and a
  # file that exists only there is not a Drive source at all. They lend their title and
  # an in_zotero flag to every other copy of the same file.
  $ordered = $g.Group | Sort-Object reference, priority, path
  $ref = @($g.Group | Where-Object reference)
  # Named collections follow a file across every copy, so the canonical copy keeps them.
  $tags = @($g.Group | ForEach-Object {
    if ($_.source -eq 'TB Training Info') { 'TB (Barbeau)' }
    if ($_.path -match '(?i)landon[ _]?evans') { 'Landon Evans' }
  }) | Sort-Object -Unique
  $i = 0
  foreach ($row in $ordered) {
    $row.dup_key = $g.Name; $row.dup_count = $g.Count; $row.collections = $tags -join ';'
    $row.canonical = ($i -eq 0 -and -not $row.reference)
    $row.in_zotero = $ref.Count -gt 0
    $row.zotero_title = if ($ref.Count) { $ref[0].name -replace '\.[A-Za-z0-9]{1,5}$','' } else { '' }
    $i++
  }
}

$rows | Sort-Object source, path | Export-Csv "$outDir/manifest.csv" -NoTypeInformation -Encoding utf8

