import re, glob
q = open("docs/QUEUE.md", encoding="utf-8").read()
waves = re.findall(r"^\| (W\d+) \|(.*)$", q, re.M)
short = "\n".join(open(f, encoding="utf-8").read() for f in glob.glob("docs/shortlists/*.md"))
rows = {}
for f in glob.glob("docs/shortlists/*.md"):
    for line in open(f, encoding="utf-8"):
        c = [x.strip() for x in line.strip().strip("|").split("|")]
        if len(c) == 9 and c[0].isdigit():
            rows[c[2]] = (c[6], c[7])
moved = []
for w, rest in waves:
    c = [x.strip() for x in rest.strip().strip("|").split("|")]
    what, src, path = c[1], c[3], c[4]
    if path not in short:
        # find same item by description (description minus review-note suffix)
        base = what.split(" (")[0]
        hit = next(((d, v) for d, v in rows.items() if d.startswith(base[:50])), None)
        moved.append((w, src, path, hit[1] if hit else None))
print("wave rows:", len(waves), "paths no longer in shortlists:", len(moved))
for w, s, p, new in moved:
    print(f" {w}: {s} {p[:70]}\n      -> {new[0] + ' ' + new[1][:70] if new else 'NOT FOUND'}")

