def main() -> None:
    FILES.mkdir(parents=True, exist_ok=True)
    with open(HERE / "sample.csv", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    out_rows = []
    for r in rows:
        folder = "/".join(x for x in [r["source"], r["path"].rsplit("/", 1)[0] if "/" in r["path"] else ""] if x)
        state = {"folder": folder, "file_name": r["name"]}
        if r["zotero_title"]:
            state["zotero_title"] = r["zotero_title"]
        ext, kind = r["ext"].lower(), r["kind"]
        how = "path and name only"
        if kind in TEXT_KINDS:
            if ext in LEGACY:
                how = "no text: legacy Office format"
            else:
                native = int(r["size"] or 0) == 0
                target = FILES / f"{r['sample_id']}.{'gdoc' if native else ext or 'bin'}"
                ok = target.exists() and target.stat().st_size > 0
                if not ok:
                    ok = gws_get(r["id"], target, "text/plain" if native else None)
                if not ok:
                    how = "no text: download failed"
                else:
                    try:
                        text = " ".join(first_page(target, "gdoc" if native else ext).split())
                    except Exception as e:  # scanned, encrypted or damaged file
                        text, how = "", f"no text: {type(e).__name__}"
                    if text:
                        state["first_page"] = text[:MAX_CHARS]
                        how = "first page"
                    elif how == "path and name only":
                        how = "no text layer"
        out_rows.append({"sample_id": r["sample_id"], "state": state, "extraction": how})
        print(r["sample_id"], how, flush=True)
    path = PRIVATE / "state.jsonl"
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        for o in out_rows:
            fh.write(json.dumps(o, ensure_ascii=False, sort_keys=True) + "\n")
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    from collections import Counter
    print(Counter(o["extraction"] for o in out_rows))
    print("state.jsonl sha256", digest)


if __name__ == "__main__":
    main()
